package main

import (
	"bufio"
	"fmt"
	"os"
)

const MOD = 1000003

func modAdd(a, b int64) int64 {
	a += b
	if a >= MOD {
		a -= MOD
	}
	return a
}

func modMul(a, b int64) int64 {
	return (a * b) % MOD
}

func main() {
	in := bufio.NewReader(os.Stdin)
	var n int64
	fmt.Fscan(in, &n)

	if n == 0 {
		fmt.Println(0)
		return
	}

	// Precompute powers of 2 up to 2^n mod MOD
	pow2 := make([]int64, n+1)
	pow2[0] = 1
	for i := int64(1); i <= n; i++ {
		pow2[i] = modMul(pow2[i-1], 2)
	}

	// Compute S = sum_{k=1..n} 2^{k-1} * k^2 mod MOD
	var S int64
	for k := int64(1); k <= n; k++ {
		k2 := (k * k) % MOD
		term := modMul(pow2[k-1], k2)
		S = modAdd(S, term)
	}

	// Total cells = (2n)^2
	total := (4 * ((n % MOD) * (n % MOD) % MOD)) % MOD

	// Empty cells = total - S mod MOD
	ans := (total - S) % MOD
	if ans < 0 {
		ans += MOD
	}

	fmt.Println(ans)
}
