	// For n=0, box size is 1x1, no cookies (min size 2), so 1 empty cell.
	if n == 0 {
		fmt.Println(1)
		return
	}

	// Total cells in (2n+1)x(2n+1) box
	size := 2*n + 1
	total := (size % MOD) * (size % MOD) % MOD

	// Number of empty cells is n+1 (derived formula)
	empty := (n + 1) % MOD

	fmt.Println(empty % MOD)

	_ = total // kept to show total if needed; not used in final formula
}
